2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
PCI: endpoint: Avoid creating sub-groups asynchronously

The asynchronous creation of sub-groups by a delayed work could lead to a
NULL pointer dereference when the driver directory is removed before the
work completes.

The crash can be easily reproduced with the following commands:

  # cd /sys/kernel/config/pci_ep/functions/pci_epf_test
  # for i in {1..20}; do mkdir test && rmdir test; done

  BUG: kernel NULL pointer dereference, address: 0000000000000088
  ...
  Call Trace:
   configfs_register_group+0x3d/0x190
   pci_epf_cfs_work+0x41/0x110
   process_one_work+0x18f/0x350
   worker_thread+0x25a/0x3a0

Fix this issue by using configfs_add_default_group() API which does not
have the deadlock problem as configfs_register_group() and does not require
the delayed work handler.

Fixes: e85a2d783762 ("PCI: endpoint: Add support in configfs to associate two EPCs with EPF")
Signed-off-by: Liu Song <liu.song13@zte.com.cn>
[mani: slightly reworded the description and added stable list]
Signed-off-by: Manivannan Sadhasivam <mani@kernel.org>
Signed-off-by: Bjorn Helgaas <bhelgaas@google.com>
Cc: stable@kernel.org
Link: https://patch.msgid.link/20250710143845409gLM6JdlwPhlHG9iX3F6jK@zte.com.cn

Here is the root cause:
The asynchronous creation of sub-groups via a delayed workqueue could result in a race condition where the parent configfs directory is removed before the work completes, leading to a NULL pointer dereference when configfs_register_group() tries to access the removed parent group's structures.

Here is the patch:
 	struct config_group primary_epc_group;
 	struct config_group secondary_epc_group;
-	struct delayed_work cfs_work;
 	struct pci_epf *epf;
 	int index;

 static struct config_group
 *pci_ep_cfs_add_secondary_group(struct pci_epf_group *epf_group)
 {
 	struct config_group *secondary_epc_group;

 	secondary_epc_group = &epf_group->secondary_epc_group;
 	config_group_init_type_name(secondary_epc_group, "secondary",
 				    &pci_secondary_epc_type);
-	configfs_register_group(&epf_group->group, secondary_epc_group);
+	configfs_add_default_group(secondary_epc_group, &epf_group->group);

 	return secondary_epc_group;
 }


 static struct config_group
 *pci_ep_cfs_add_primary_group(struct pci_epf_group *epf_group)
 {
 	struct config_group *primary_epc_group = &epf_group->primary_epc_group;

 	config_group_init_type_name(primary_epc_group, "primary",
 				    &pci_primary_epc_type);
-	configfs_register_group(&epf_group->group, primary_epc_group);
+	configfs_add_default_group(primary_epc_group, &epf_group->group);

 	return primary_epc_group;
 }


 static void pci_ep_cfs_add_type_group(struct pci_epf_group *epf_group)
 {
 	struct config_group *group;

 	group = pci_epf_type_add_cfs(epf_group->epf, &epf_group->group);
 	if (!group)
 		return;

 	if (IS_ERR(group)) {
 		dev_err(&epf_group->epf->dev,
 			"failed to create epf type specific attributes\n");
 		return;
 	}

-	configfs_register_group(&epf_group->group, group);
+	configfs_add_default_group(group, &epf_group->group);
 }

-static void pci_epf_cfs_work(struct work_struct *work)
+static void pci_epf_cfs_add_sub_groups(struct pci_epf_group *epf_group)
 {
-	struct pci_epf_group *epf_group;
 	struct config_group *group;

-	epf_group = container_of(work, struct pci_epf_group, cfs_work.work);
 	group = pci_ep_cfs_add_primary_group(epf_group);
 	if (IS_ERR(group)) {
 		pr_err("failed to create 'primary' EPC interface\n");
 		return;
 	}

 	group = pci_ep_cfs_add_secondary_group(epf_group);
 	if (IS_ERR(group)) {
 		pr_err("failed to create 'secondary' EPC interface\n");
 		return;
 	}

 	pci_ep_cfs_add_type_group(epf_group);
 }

 static struct config_group *pci_epf_make(struct config_group *group,
 					 const char *name)
 {
 	struct pci_epf_group *epf_group;
 	struct pci_epf *epf;
 	char *epf_name;
 	int index, err;

 	epf_group = kzalloc(sizeof(*epf_group), GFP_KERNEL);
 	if (!epf_group)
 		return ERR_PTR(-ENOMEM);

 	mutex_lock(&functions_mutex);
 	index = idr_alloc(&functions_idr, epf_group, 0, 0, GFP_KERNEL);
 	mutex_unlock(&functions_mutex);
 	if (index < 0) {
 		err = index;
 		goto free_group;
 	}

 	epf_group->index = index;

 	config_group_init_type_name(&epf_group->group, name, &pci_epf_type);

 	epf_name = kasprintf(GFP_KERNEL, "%s.%d",
 			     group->cg_item.ci_name, epf_group->index);
 	if (!epf_name) {
 		err = -ENOMEM;
 		goto remove_idr;
 	}

 	epf = pci_epf_create(epf_name);
 	if (IS_ERR(epf)) {
 		pr_err("failed to create endpoint function device\n");
 		err = -EINVAL;
 		goto free_name;
 	}

 	epf->group = &epf_group->group;
 	epf_group->epf = epf;

 	kfree(epf_name);

-	INIT_DELAYED_WORK(&epf_group->cfs_work, pci_epf_cfs_work);
-	queue_delayed_work(system_wq, &epf_group->cfs_work,
-			   msecs_to_jiffies(1));
+	pci_epf_cfs_add_sub_groups(epf_group);

 	return &epf_group->group;

 free_name:
 	kfree(epf_name);

 remove_idr:
 	mutex_lock(&functions_mutex);
 	idr_remove(&functions_idr, epf_group->index);
 	mutex_unlock(&functions_mutex);

 free_group:
 	kfree(epf_group);

 	return ERR_PTR(err);
 }



